(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.018-t*0.22)*18 + Math.sin(x*0.015+t*0.28)*12;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025+t*0.15)*8 + Math.cos(my*0.02-t*0.12)*6;
  const w2y = Math.cos(my*0.022-t*0.17)*8 + Math.sin(mx*0.019+t*0.2)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.9],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.8],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,1.2],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.7],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,1.0],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.11,1.4,1.3],
    [400+Math.cos(t*0.55+1)*60,220+Math.sin(t*0.75+4)*40,0.13,1.6,0.85],
    [200+Math.sin(t*0.38+6)*110,60+Math.cos(t*0.48+5)*70,0.075,2.1,0.95],
    [300+Math.cos(t*0.42+3)*90,100+Math.sin(t*0.58+1)*80,0.095,1.8,1.05]
  ];
  let aS=0,iS=0,a2=0,i2=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((mx-sX*0.8+cx*0.2)**2+(my-sY*0.8+cy*0.2)**2);
    aS+=Math.sin(d*f-t*sp)*w; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    a2+=Math.sin(d2*f*0.5-t*sp*0.8+2)*w; i2+=Math.sin(d2*f*0.4+t*sp*0.5+3)*w;
  }
  const n=src.length, act=aS/n, inh=iS/n, act2=a2/n, inh2=i2/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+sy*0.06-t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
