    +Math.sin(dist*0.03-ang*2-t*0.8)*0.5)*0.3;
  const ring=Math.sin(dist*0.08-t*0.6)*Math.cos(ang*6+t*0.3)*0.3;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act2-inh2*0.65+r1*0.4+ring)*1.8);
  const reaction=Math.tanh(r1*0.6+r2*0.4+ring*0.15);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)
    +Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.25;
  const fine=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.25-t*2.5)*0.1;
  const blend=reaction*0.65+cell*0.2+fine*0.15, v=blend*0.5+0.5;
  const pal=[[5,12,52],[10,45,90],[15,85,120],[20,140,130],[80,170,110],
    [180,190,70],[220,170,50],[215,120,55],[190,70,60],[140,40,70],
    [80,20,60],[30,15,55],[5,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(r2)*0.1;
  const edgeMag=Math.abs(reaction);
  const glow=edgeMag>0.6?1.0+(edgeMag-0.6)*0.5:1.0;
  const hs=Math.sin(ang*2+t*0.3)*0.08, fl=lum*glow;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*fl*(1+hs)))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*fl*(1-hs*0.5)))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*fl*(1+hs*0.3)))|0
  ];
}
